import app from 'flarum/forum/app';
import Composer from './Composer';
import { Lightbox, MergeModal, ReportModal } from './modals';
export function openComposer(attrs) {
  app.modal.show(Composer, attrs);
}
export function openAddItem(category) {
  if (!app.session.user) {
    app.modal.show(() => flarum.reg.asyncModuleImport('flarum/forum/components/LogInModal'));
    return;
  }
  app.modal.show(Composer, {
    category
  });
}
export function openReport(subjectType, subjectId) {
  app.modal.show(ReportModal, {
    subjectType,
    subjectId
  });
}
export function openMerge(item) {
  app.modal.show(MergeModal, {
    item
  });
}
export function openLightbox(photos, index) {
  app.modal.show(Lightbox, {
    photos,
    index
  });
}
flarum.reg.add('ernestdefoe-community-reviews', 'forum/ui/open', { openComposer: openComposer,openAddItem: openAddItem,openReport: openReport,openMerge: openMerge,openLightbox: openLightbox, });